package sohal.lld.snakeladder.board;import sohal.lld.snakeladder.entity.Entity;import sohal.lld.snakeladder.entity.Ladder;import sohal.lld.snakeladder.entity.Snake;import java.util.*;public class Board {    private final int size;    private Map<Integer, Entity> snakesAndLadders;    public Board(int size, Map<Integer, Entity> snakesAndLadders) {        this.size = size;        this.snakesAndLadders = snakesAndLadders;        listEntities();    }    public int getFinalPosition(int rolledTo) {        if(rolledTo < 0 || rolledTo >= size) return -1;        for(Map.Entry<Integer, Entity> entry : snakesAndLadders.entrySet()) {            if(entry.getValue().getStart() == rolledTo) {                return entry.getValue().getEnd();            }        }        return rolledTo;    }    private void listEntities() {        for (Entity entity : snakesAndLadders.values()) {            if(entity instanceof Snake) {                Snake snake = (Snake) entity;                System.out.println("Snake: "+ snake);            } else if(entity instanceof Ladder) {                Ladder ladder = (Ladder) entity;                System.out.println("Ladder :" + ladder);            }        }    }}